import React, { useState } from 'react';
import { ref, update } from 'firebase/database';
import { database } from '../Firebase';
import 'bootstrap/dist/css/bootstrap.min.css';

const BulkJsonUploader = () => {
  const [group, setGroup] = useState('sso');
  const [bulkJson, setBulkJson] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const parsedData = JSON.parse(bulkJson);

      // Merge new data with existing at /group/
      await update(ref(database, group), parsedData);

      alert('Bulk data uploaded and merged successfully!');
      setBulkJson('');
    } catch (err) {
      alert('Invalid JSON or Firebase error: ' + err.message);
    }
  };

  return (
    <div className='container p-4'>
      <h4 className='mb-3'>Upload Bulk JSON to Firebase</h4>
      <form onSubmit={handleSubmit}>
        <div className='row'>
          <div className='col-md-4 mb-3'>
            <label className='form-label'>Department Group *</label>
            <select
              className='form-select'
              value={group}
              onChange={(e) => setGroup(e.target.value)}
              required
            >
              <option value='sso'>SSO</option>
              <option value='qc'>QC</option>
              <option value='naps'>NAPS</option>
              <option value='supervisor'>Supervisor (Permanent)</option>
            </select>
          </div>
        </div>

        <div className='mb-3'>
          <label className='form-label'>Paste Complete JSON</label>
          <textarea
            className='form-control'
            rows={12}
            value={bulkJson}
            onChange={(e) => setBulkJson(e.target.value)}
            placeholder={`{\n  "emp001": { "name": "John", ... },\n  "emp002": { "name": "Alice", ... }\n}`}
            required
          />
        </div>

        <button type='submit' className='btn btn-primary'>
          Upload to Firebase
        </button>
      </form>
    </div>
  );
};

export default BulkJsonUploader;
