import React, { useState, useEffect } from 'react';
import { ref, get, update } from 'firebase/database';
import { database } from '../Firebase';
import { Modal, Button } from 'react-bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';

const sizes = {
  tshirt: ['S(36)', 'M(38)', 'L(40)', 'XL(42)', 'XXL(44)', 'XXXL(46)'],
  shirt_full: ['S(36)', 'M(38)', 'L(40)', 'XL(42)', 'XXL(44)', 'XXXL(46)'],
  shirt_half: ['S(36)', 'M(38)', 'L(40)', 'XL(42)', 'XXL(44)', 'XXXL(46)'],
  trouser: [
    '28x40',
    '28x42',
    '28x44',
    '28x46',
    '30x40',
    '30x42',
    '30x44',
    '30x46',
    '32x40',
    '32x42',
    '32x44',
    '32x46',
    '34x40',
    '34x42',
    '34x44',
    '34x46',
    '36x40',
    '36x42',
    '36x44',
    '36x46',
    '38x40',
    '38x42',
    '38x44',
    '38x46',
    '40x40',
    '40x42',
    '40x44',
    '40x46',
    '42x40',
    '42x42',
    '42x44',
    '42x46',
    '44x40',
    '44x42',
    '44x44',
    '44x46',
    'Other(cloth)',
  ],
};

export default function New() {
  const groups = ['sso', 'qc', 'naps', 'supervisor'];
  const [empId, setEmpId] = useState('');
  const [empData, setEmpData] = useState(null);
  const [dept, setDept] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [confirmOverLimit, setConfirmOverLimit] = useState(false);

  const [form, setForm] = useState({
    cap: 0,
    safety_shoes: { size: '', quantity: 0 },
    tshirt: {},
    shirt_full: {},
    shirt_half: {},
    trouser: {},
  });

  const [pointsUsed, setPointsUsed] = useState(0);
  const [availablePoints, setAvailablePoints] = useState(100);

  const searchEmployee = async () => {
    const idLower = empId.trim().toLowerCase();
    for (const grp of groups) {
      const snap = await get(ref(database, grp));
      if (snap.exists()) {
        const data = snap.val();
        for (const key in data) {
          if (key.toLowerCase() === idLower) {
            setEmpId(key);
            setEmpData(data[key]);
            setDept(grp);
            calculateAvailablePoints(data[key].items || {});
            return;
          }
        }
      }
    }
    alert('Employee not found.');
  };

  const calculateAvailablePoints = (itemsData) => {
    let used = 0;

    if (!itemsData || Object.keys(itemsData).length === 0) {
      setAvailablePoints(100);
      return;
    }

    Object.entries(itemsData).forEach(([itemType, itemValue]) => {
      if (itemType === 'cap') {
        used += 0;
      } else if (itemType === 'safety_shoes') {
        Object.values(itemValue || {}).forEach((qty) => {
          used += qty * 20;
        });
      } else if (['tshirt', 'shirt_full', 'shirt_half'].includes(itemType)) {
        Object.values(itemValue || {}).forEach((qty) => {
          used +=
            qty * { tshirt: 10, shirt_full: 15, shirt_half: 15 }[itemType];
        });
      } else if (itemType === 'trouser') {
        Object.values(itemValue || {}).forEach((qty) => {
          used += qty * 20;
        });
      }
    });

    const calculated = Math.max(0, 100 - used);
    setAvailablePoints(calculated);
  };

  const handleItemChange = (field, size, value) => {
    let qty = Math.max(0, Math.min(parseInt(value) || 0, 6));
    if (field === 'cap') qty = Math.min(qty, 1);
    if (field === 'safety_shoes' && size === 'quantity') qty = Math.min(qty, 1);

    setForm((prev) => {
      if (field === 'cap') return { ...prev, cap: qty };
      if (field === 'safety_shoes') {
        return {
          ...prev,
          safety_shoes: {
            ...prev.safety_shoes,
            [size]: size === 'quantity' ? qty : value,
          },
        };
      }
      return {
        ...prev,
        [field]: {
          ...prev[field],
          [size]: qty,
        },
      };
    });
  };

  const calculatePoints = () => {
    let total = 0;
    if (form.cap > 0) total += 0;
    if (form.safety_shoes.quantity > 0)
      total += form.safety_shoes.quantity * 20;

    ['tshirt', 'shirt_full', 'shirt_half', 'trouser'].forEach((item) => {
      Object.entries(form[item] || {}).forEach(([size, qty]) => {
        total +=
          qty *
          { tshirt: 10, shirt_full: 15, shirt_half: 15, trouser: 20 }[item];
      });
    });

    setPointsUsed(total);
  };

  useEffect(() => {
    calculatePoints();
  }, [form]);

  const handleSubmit = async () => {
    if (!empData) return;

    // Set Indian time (IST)
    const now = new Date();
    const istOffset = 5.5 * 60 * 60000; // 5 hours 30 minutes in ms
    const ist = new Date(now.getTime() + istOffset);
    const timestamp = ist.toISOString().replace('T', ' ').slice(0, 19);

    const itemsPath = `${dept}/${empId}/items`;
    const empRef = ref(database, itemsPath);
    const existingSnap = await get(empRef);
    const existing = existingSnap.exists() ? existingSnap.val() : {};
    const merged = { ...existing };

    let totalUsed = 0;
    if (form.cap > 0) {
      merged.cap = (merged.cap || 0) + form.cap;
      totalUsed += 0;
    }

    if (form.safety_shoes.quantity > 0 && form.safety_shoes.size) {
      merged.safety_shoes = merged.safety_shoes || {};
      merged.safety_shoes[form.safety_shoes.size] =
        (merged.safety_shoes[form.safety_shoes.size] || 0) +
        form.safety_shoes.quantity;
      totalUsed += form.safety_shoes.quantity * 20;
    }

    ['tshirt', 'shirt_full', 'shirt_half', 'trouser'].forEach((item) => {
      Object.entries(form[item] || {}).forEach(([sz, qty]) => {
        if (qty > 0) {
          merged[item] = merged[item] || {};
          merged[item][sz] = (merged[item][sz] || 0) + qty;
          totalUsed +=
            qty *
            { tshirt: 10, shirt_full: 15, shirt_half: 15, trouser: 20 }[item];
        }
      });
    });

    if (totalUsed > availablePoints && !confirmOverLimit) {
      alert('Exceeds available points. Please confirm override.');
      return;
    }

    const updates = {};
    updates[itemsPath] = merged;
    updates[`${dept}/${empId}/points`] = (empData.points ?? 100) - totalUsed;
    updates[`${dept}/${empId}/last_update`] = timestamp;
    updates[`logs/${empId}/${timestamp}/issued`] = merged;

    await update(ref(database), updates);

    alert('Items issued.');
    setEmpData(null);
    setEmpId('');
    setForm({
      cap: 0,
      safety_shoes: { size: '', quantity: 0 },
      tshirt: {},
      shirt_full: {},
      shirt_half: {},
      trouser: {},
    });
    setConfirmOverLimit(false);
    setPointsUsed(0);
  };

  return (
    <div className='container mt-4'>
      <h4>Employee Item Issue</h4>

      <div className='d-flex mb-3'>
        <input
          className='form-control me-2'
          placeholder='Employee ID'
          value={empId}
          onChange={(e) => setEmpId(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && searchEmployee()}
        />
        <Button onClick={searchEmployee}>Search</Button>
      </div>

      {empData && (
        <div className='border p-3 bg-light rounded mb-4'>
          <div className='d-flex justify-content-between'>
            <div>
              <strong>Emp ID:</strong> {empId} <br />
              <strong>Name:</strong> {empData.name}
              <br />
              <Button
                variant='info'
                size='sm'
                onClick={() => setShowModal(true)}
                className='mt-2'
              >
                View Details
              </Button>
            </div>
            <div className='px-3 py-0 my-0 rounded'>
              <strong>Points:</strong> {pointsUsed} / {availablePoints}
            </div>
          </div>

          {pointsUsed > availablePoints && (
            <div className='form-check text-danger my-2'>
              <input
                type='checkbox'
                className='form-check-input'
                id='overLimit'
                checked={confirmOverLimit}
                onChange={(e) => setConfirmOverLimit(e.target.checked)}
              />
              <label className='form-check-label' htmlFor='overLimit'>
                Confirm override limit
              </label>
            </div>
          )}

          {/* Form Items */}
          <div className='row my-3'>
            <div className='col-md-6'>
              <label>Cap</label>
              <input
                type='number'
                className='form-control'
                value={form.cap}
                onChange={(e) => handleItemChange('cap', '', e.target.value)}
                min='0'
                max='1'
                onWheel={(e) => e.target.blur()}
              />
            </div>
            <div className='col-md-6'>
              <label>Safety Shoes</label>
              <div className='d-flex'>
                <input
                  type='text'
                  className='form-control me-2'
                  placeholder='Size'
                  value={form.safety_shoes.size}
                  onChange={(e) =>
                    handleItemChange('safety_shoes', 'size', e.target.value)
                  }
                />
                <input
                  type='number'
                  className='form-control'
                  placeholder='Qty'
                  value={form.safety_shoes.quantity}
                  onChange={(e) =>
                    handleItemChange('safety_shoes', 'quantity', e.target.value)
                  }
                  min='0'
                  max='1'
                  onWheel={(e) => e.target.blur()}
                />
              </div>
            </div>
          </div>

          {['tshirt', 'shirt_full', 'shirt_half', 'trouser'].map((item) => (
            <div key={item} className='border p-2 mb-3 rounded'>
              <h6 className='text-uppercase'>{item.replace('_', ' ')}</h6>
              <div className='row'>
                {sizes[item].map((sz) => (
                  <div key={sz} className='col-4 col-md-2 mb-2'>
                    <label>{sz}</label>
                    <input
                      type='number'
                      className='form-control'
                      min='0'
                      max='6'
                      value={form[item][sz] || ''}
                      onChange={(e) =>
                        handleItemChange(item, sz, e.target.value)
                      }
                      onWheel={(e) => e.target.blur()}
                    />
                  </div>
                ))}
              </div>
            </div>
          ))}

          <Button variant='success' onClick={handleSubmit}>
            Submit
          </Button>
        </div>
      )}

      {/* Details Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size='lg'>
        <Modal.Header closeButton>
          <Modal.Title>Employee Details</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {empData && (
            <>
              {/* Show basic fields except name/items/resources */}
              {Object.entries(empData).map(([key, value]) => {
                if (
                  ['name', 'items', 'additional_resources'].includes(key) ||
                  typeof value === 'object'
                )
                  return null;

                const label = key
                  .replace(/_/g, ' ')
                  .replace(/\b\w/g, (char) => char.toUpperCase());

                return (
                  <p key={key}>
                    <strong>{label}:</strong> {value}
                  </p>
                );
              })}

              {/* ITEMS SECTION */}
              {'items' in empData && (
                <>
                  <hr />
                  <h6>Issued Items:</h6>
                  <ul>
                    {Object.entries(empData.items).map(
                      ([itemType, itemValue]) => (
                        <li key={itemType}>
                          <strong>{itemType}:</strong>{' '}
                          {typeof itemValue === 'object' ? (
                            <ul>
                              {Object.entries(itemValue).map(([size, qty]) => (
                                <li key={size}>
                                  {size}: {qty}
                                </li>
                              ))}
                            </ul>
                          ) : (
                            <span>{itemValue}</span> // for cap: 1
                          )}
                        </li>
                      )
                    )}
                  </ul>
                </>
              )}

              {/* ADDITIONAL RESOURCES SECTION */}
              {'additional_resources' in empData && (
                <>
                  <hr />
                  <h6>Additional Resources:</h6>
                  <ul>
                    {Object.entries(empData.additional_resources).map(
                      ([itemType, itemValue]) => (
                        <li key={itemType}>
                          <strong>{itemType}:</strong>{' '}
                          {typeof itemValue === 'object' ? (
                            <ul>
                              {Object.entries(itemValue).map(([size, qty]) => (
                                <li key={size}>
                                  {size}: {qty}
                                </li>
                              ))}
                            </ul>
                          ) : (
                            <span>{itemValue}</span> // for cap: 1
                          )}
                        </li>
                      )
                    )}
                  </ul>
                </>
              )}
            </>
          )}
        </Modal.Body>

        <Modal.Footer>
          <Button onClick={() => setShowModal(false)}>Close</Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}
