import React, { useState, useEffect } from 'react';
import { ref, get, update } from 'firebase/database';
import { database } from '../Firebase';
import { Button, Modal } from 'react-bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';

const sizes = {
  tshirt: ['S(36)', 'M(38)', 'L(40)', 'XL(42)', 'XXL(44)', 'XXXL(46)'],
  shirt_full: ['S(36)', 'M(38)', 'L(40)', 'XL(42)', 'XXL(44)', 'XXXL(46)'],
  shirt_half: ['S(36)', 'M(38)', 'L(40)', 'XL(42)', 'XXL(44)', 'XXXL(46)'],
  trouser: [
    '28x40',
    '28x42',
    '28x44',
    '28x46',
    '30x40',
    '30x42',
    '30x44',
    '30x46',
    '32x40',
    '32x42',
    '32x44',
    '32x46',
    '34x40',
    '34x42',
    '34x44',
    '34x46',
    '36x40',
    '36x42',
    '36x44',
    '36x46',
    '38x40',
    '38x42',
    '38x44',
    '38x46',
    '40x40',
    '40x42',
    '40x44',
    '40x46',
    '42x40',
    '42x42',
    '42x44',
    '42x46',
    '44x40',
    '44x42',
    '44x44',
    '44x46',
    'Other(cloth)',
  ],
};

export default function Exchange() {
  const groups = ['sso', 'qc', 'naps', 'supervisor'];
  const [empId, setEmpId] = useState('');
  const [empData, setEmpData] = useState(null);
  const [dept, setDept] = useState('');
  const [showModal, setShowModal] = useState(false);

  const emptyForm = {
    cap: 0,
    safety_shoes: { size: '', quantity: 0 },
    tshirt: {},
    shirt_full: {},
    shirt_half: {},
    trouser: {},
  };

  const [formIssue, setFormIssue] = useState({ ...emptyForm });
  const [formReturn, setFormReturn] = useState({ ...emptyForm });

  const searchEmployee = async () => {
    const idLower = empId.trim().toLowerCase();
    for (const grp of groups) {
      const snap = await get(ref(database, grp));
      if (snap.exists()) {
        const data = snap.val();
        for (const key in data) {
          if (key.toLowerCase() === idLower) {
            setEmpId(key);
            setEmpData(data[key]);
            setDept(grp);
            return;
          }
        }
      }
    }
    alert('Employee not found.');
  };

  const handleItemChange = (formSetter, field, size, value) => {
    let qty = Math.max(0, Math.min(parseInt(value) || 0, 6));
    if (field === 'cap') qty = Math.min(qty, 1);
    if (field === 'safety_shoes' && size === 'quantity') qty = Math.min(qty, 1);

    formSetter((prev) => {
      if (field === 'cap') return { ...prev, cap: qty };
      if (field === 'safety_shoes') {
        return {
          ...prev,
          safety_shoes: {
            ...prev.safety_shoes,
            [size]: size === 'quantity' ? qty : value,
          },
        };
      }
      return {
        ...prev,
        [field]: {
          ...prev[field],
          [size]: qty,
        },
      };
    });
  };

  const handleSubmit = async () => {
    if (!empData) return;

    const now = new Date();
    const istOffset = 5.5 * 60 * 60 * 1000;
    const istTime = new Date(now.getTime() + istOffset);
    const timestamp = istTime.toISOString().replace('T', ' ').slice(0, 19);
    const timeOnly = istTime.toLocaleTimeString('en-IN');

    const empPath = `${dept}/${empId}`;
    const empRef = ref(database, empPath);
    const snap = await get(empRef);
    const existing = snap.exists() ? snap.val() : {};

    const updatedItems = { ...existing.items } || {};

    const processForm = (form, factor) => {
      if (form.cap > 0) {
        updatedItems.cap = (updatedItems.cap || 0) + factor * form.cap;
        if (updatedItems.cap < 0) updatedItems.cap = 0;
      }

      if (form.safety_shoes.quantity > 0 && form.safety_shoes.size) {
        const sz = form.safety_shoes.size;
        updatedItems.safety_shoes = updatedItems.safety_shoes || {};
        updatedItems.safety_shoes[sz] =
          (updatedItems.safety_shoes[sz] || 0) +
          factor * form.safety_shoes.quantity;
        if (updatedItems.safety_shoes[sz] < 0)
          updatedItems.safety_shoes[sz] = 0;
      }

      ['tshirt', 'shirt_full', 'shirt_half', 'trouser'].forEach((item) => {
        Object.entries(form[item] || {}).forEach(([sz, qty]) => {
          if (qty > 0) {
            updatedItems[item] = updatedItems[item] || {};
            updatedItems[item][sz] =
              (updatedItems[item][sz] || 0) + factor * qty;
            if (updatedItems[item][sz] < 0) updatedItems[item][sz] = 0;
          }
        });
      });
    };

    processForm(formReturn, -1);
    processForm(formIssue, 1);

    const removeEmptyEntries = (obj) => {
      const cleaned = {};
      for (const [key, val] of Object.entries(obj)) {
        if (typeof val === 'object' && val !== null) {
          const nested = removeEmptyEntries(val);
          if (Object.keys(nested).length > 0) cleaned[key] = nested;
        } else if (val > 0 || (typeof val === 'string' && val.trim() !== '')) {
          cleaned[key] = val;
        }
      }
      return cleaned;
    };

    const updates = {};
    updates[`${empPath}/items`] = removeEmptyEntries(updatedItems); // <--- 🔥 Updated here!
    updates[`${empPath}/last_update`] = `${istTime.getFullYear()}-${String(
      istTime.getMonth() + 1
    ).padStart(2, '0')}`;
    updates[`${empPath}/time`] = timeOnly;

    const cleanedReturn = removeEmptyEntries(formReturn);
    const cleanedIssue = removeEmptyEntries(formIssue);

    if (Object.keys(cleanedReturn).length > 0)
      updates[`logs/${empId}/exchange/return/${timestamp}`] = cleanedReturn;
    if (Object.keys(cleanedIssue).length > 0)
      updates[`logs/${empId}/exchange/issue/${timestamp}`] = cleanedIssue;

    await update(ref(database), updates);
    alert('Exchange processed.');

    setEmpData(null);
    setEmpId('');
    setFormIssue({ ...emptyForm });
    setFormReturn({ ...emptyForm });
  };

  return (
    <div className='container mt-4 position-relative'>
      <h4>Exchange Items</h4>
      <div className='d-flex mb-3'>
        <input
          className='form-control me-2'
          placeholder='Employee ID'
          value={empId}
          onChange={(e) => setEmpId(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && searchEmployee()}
        />
        <Button onClick={searchEmployee}>Search</Button>
      </div>

      {empData && (
        <div className='border p-3 bg-light rounded mb-4'>
          <div className='d-flex justify-content-between'>
            <div>
              <strong>Emp ID:</strong> {empId} <br />
              <strong>Name:</strong> {empData.name}
              <br />
              <Button
                variant='info'
                size='sm'
                onClick={() => setShowModal(true)}
                className='mt-2'
              >
                View Details
              </Button>
            </div>
          </div>

          <hr />
          <h5>Issue Items</h5>
          {renderForm(formIssue, (field, size, value) =>
            handleItemChange(setFormIssue, field, size, value)
          )}

          <hr />
          <hr />
          <hr />
          <h5>Return Items</h5>
          {renderForm(formReturn, (field, size, value) =>
            handleItemChange(setFormReturn, field, size, value)
          )}

          <Button variant='success' className='mt-3' onClick={handleSubmit}>
            Submit Exchange
          </Button>
        </div>
      )}

      {/* Fixed Right Summary Box */}
      <div
        style={{
          position: 'fixed',
          top: '100px',
          right: '30px',
          width: '120px',
          maxHeight: '80vh',
          overflowY: 'auto',
          backgroundColor: 'transparent',
          border: '1px solid #ccc',
          borderRadius: '8px',
          padding: '10px',
          zIndex: 1000,
        }}
      >
        <ul className='list-unstyled'>
          {empData?.items &&
            Object.entries(empData.items).map(([itemKey, itemVal]) => {
              if (typeof itemVal === 'number') {
                return itemVal > 0 ? (
                  <li key={itemKey}>
                    {itemKey}: {itemVal}
                  </li>
                ) : null;
              } else if (typeof itemVal === 'object') {
                return (
                  <li key={itemKey}>
                    {itemKey}:
                    <ul>
                      {Object.entries(itemVal).map(([sz, qty]) =>
                        qty > 0 ? (
                          <li key={sz}>
                            {sz}: {qty}
                          </li>
                        ) : null
                      )}
                    </ul>
                  </li>
                );
              } else return null;
            })}
        </ul>
      </div>

      {/* Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size='lg'>
        <Modal.Header closeButton>
          <Modal.Title>Employee Details</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {empData &&
            Object.entries(empData).map(([key, value]) => {
              if (
                ['name', 'items', 'additional_resources'].includes(key) ||
                typeof value === 'object'
              )
                return null;
              const label = key
                .replace(/_/g, ' ')
                .replace(/\b\w/g, (char) => char.toUpperCase());
              return (
                <p key={key}>
                  <strong>{label}:</strong> {value}
                </p>
              );
            })}
          {empData?.items && (
            <>
              <hr />
              <h6>Issued Items:</h6>
              <ul>
                {Object.entries(empData.items).map(([k, v]) => (
                  <li key={k}>
                    <strong>{k}:</strong>{' '}
                    {typeof v === 'object' ? (
                      <ul>
                        {Object.entries(v).map(([sz, qt]) => (
                          <li key={sz}>
                            {sz}: {qt}
                          </li>
                        ))}
                      </ul>
                    ) : (
                      <span>{v}</span>
                    )}
                  </li>
                ))}
              </ul>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button onClick={() => setShowModal(false)}>Close</Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}

// Render reusable form
function renderForm(form, handleChange) {
  return (
    <>
      <div className='row my-3'>
        <div className='col-md-6'>
          <label>Cap</label>
          <input
            type='number'
            className='form-control'
            value={form.cap}
            onChange={(e) => handleChange('cap', '', e.target.value)}
            min='0'
            max='1'
            onWheel={(e) => e.target.blur()}
          />
        </div>
        <div className='col-md-6'>
          <label>Safety Shoes</label>
          <div className='d-flex'>
            <input
              type='text'
              className='form-control me-2'
              placeholder='Size'
              value={form.safety_shoes.size}
              onChange={(e) =>
                handleChange('safety_shoes', 'size', e.target.value)
              }
            />
            <input
              type='number'
              className='form-control'
              placeholder='Qty'
              value={form.safety_shoes.quantity}
              onChange={(e) =>
                handleChange('safety_shoes', 'quantity', e.target.value)
              }
              min='0'
              max='1'
              onWheel={(e) => e.target.blur()}
            />
          </div>
        </div>
      </div>

      {['tshirt', 'shirt_full', 'shirt_half', 'trouser'].map((item) => (
        <div key={item} className='border p-2 mb-3 rounded'>
          <h6 className='text-uppercase'>{item.replace('_', ' ')}</h6>
          <div className='row'>
            {sizes[item].map((sz) => (
              <div key={sz} className='col-4 col-md-2 mb-2'>
                <label>{sz}</label>
                <input
                  type='number'
                  className='form-control'
                  min='0'
                  max='6'
                  value={form[item][sz] || ''}
                  onChange={(e) => handleChange(item, sz, e.target.value)}
                  onWheel={(e) => e.target.blur()}
                />
              </div>
            ))}
          </div>
        </div>
      ))}
    </>
  );
}
